import fs from "fs-extra";
import path from "path";

export interface ProjectInfo {
  framework: "express" | "node" | "fastify" | "unknown";
  hasTypeScript: boolean;
  hasSrcDir: boolean;
  packageManager: "npm" | "pnpm" | "yarn" | "bun";
  serverEntry: string; // main server file (app.js, server.js, index.js)
  serverType: "express" | "fastify" | "vanilla" | "unknown";
}

/**
 * Detect project information for backend servers
 */
export async function detectProject(cwd: string): Promise<ProjectInfo> {
  const info: ProjectInfo = {
    framework: "unknown",
    hasTypeScript: false,
    hasSrcDir: false,
    packageManager: "npm",
    serverEntry: "index.js",
    serverType: "unknown",
  };

  // Check package.json for server dependencies and scripts
  const packageJsonPath = path.join(cwd, "package.json");
  if (await fs.pathExists(packageJsonPath)) {
    const packageJson = await fs.readJson(packageJsonPath);
    
    // Check for Express
    if (
      packageJson.dependencies?.express ||
      packageJson.devDependencies?.express
    ) {
      info.framework = "express";
      info.serverType = "express";
    }
    
    // Check for Fastify
    if (
      packageJson.dependencies?.fastify ||
      packageJson.devDependencies?.fastify
    ) {
      info.framework = "fastify";
      info.serverType = "fastify";
    }
    
    // If no specific framework but has common server dependencies, consider it Node.js
    if (info.framework === "unknown" && (
      packageJson.dependencies?.cors ||
      packageJson.dependencies?.helmet ||
      packageJson.dependencies?.morgan ||
      packageJson.dependencies?.['body-parser'] ||
      packageJson.scripts?.start ||
      packageJson.scripts?.dev ||
      packageJson.scripts?.server
    )) {
      info.framework = "node";
      info.serverType = "vanilla";
    }
    
    // Check for TypeScript
    if (
      packageJson.dependencies?.typescript ||
      packageJson.devDependencies?.typescript ||
      packageJson.devDependencies?.['@types/node']
    ) {
      info.hasTypeScript = true;
    }
    
    // Detect server entry point
    if (packageJson.main) {
      info.serverEntry = packageJson.main;
    } else if (packageJson.scripts?.start) {
      const startScript = packageJson.scripts.start;
      if (startScript.includes('server.js')) {
        info.serverEntry = 'server.js';
      } else if (startScript.includes('app.js')) {
        info.serverEntry = 'app.js';
      } else if (startScript.includes('index.js')) {
        info.serverEntry = 'index.js';
      }
    }
  }

  // Check for TypeScript config
  const tsConfigPath = path.join(cwd, "tsconfig.json");
  if (await fs.pathExists(tsConfigPath)) {
    info.hasTypeScript = true;
    if (info.serverEntry.endsWith('.js')) {
      info.serverEntry = info.serverEntry.replace('.js', '.ts');
    }
  }

  // Check for src directory
  const srcDir = path.join(cwd, "src");
  info.hasSrcDir = await fs.pathExists(srcDir);

  // Try to find actual server file
  const possibleEntries = [
    'app.js', 'app.ts', 
    'server.js', 'server.ts', 
    'index.js', 'index.ts',
    'main.js', 'main.ts'
  ];
  
  for (const entry of possibleEntries) {
    const entryPath = info.hasSrcDir 
      ? path.join(cwd, 'src', entry)
      : path.join(cwd, entry);
    
    if (await fs.pathExists(entryPath)) {
      info.serverEntry = entry;
      if (entry.endsWith('.ts')) {
        info.hasTypeScript = true;
      }
      break;
    }
  }

  // Detect package manager
  if (await fs.pathExists(path.join(cwd, "pnpm-lock.yaml"))) {
    info.packageManager = "pnpm";
  } else if (await fs.pathExists(path.join(cwd, "yarn.lock"))) {
    info.packageManager = "yarn";
  } else if (await fs.pathExists(path.join(cwd, "bun.lockb"))) {
    info.packageManager = "bun";
  } else {
    info.packageManager = "npm";
  }

  return info;
}

/**
 * Get the appropriate directory for server components
 */
export function getServerComponentDir(projectInfo: ProjectInfo, cwd: string): string {
  if (projectInfo.hasSrcDir) {
    return path.join(cwd, "src");
  }
  return cwd;
}

/**
 * Get the routes directory for Express/server components
 */
export function getRoutesDir(projectInfo: ProjectInfo, cwd: string): string {
  const baseDir = getServerComponentDir(projectInfo, cwd);
  return path.join(baseDir, "routes");
}

/**
 * Get the controllers directory for server components
 */
export function getControllersDir(projectInfo: ProjectInfo, cwd: string): string {
  const baseDir = getServerComponentDir(projectInfo, cwd);
  return path.join(baseDir, "controllers");
}

/**
 * Get the models directory for server components
 */
export function getModelsDir(projectInfo: ProjectInfo, cwd: string): string {
  const baseDir = getServerComponentDir(projectInfo, cwd);
  return path.join(baseDir, "models");
}

/**
 * Get the middleware directory for server components
 */
export function getMiddlewareDir(projectInfo: ProjectInfo, cwd: string): string {
  const baseDir = getServerComponentDir(projectInfo, cwd);
  return path.join(baseDir, "middleware");
}

/**
 * Get the utils directory for server components
 */
export function getUtilsDir(projectInfo: ProjectInfo, cwd: string): string {
  const baseDir = getServerComponentDir(projectInfo, cwd);
  return path.join(baseDir, "utils");
}
