import fs from "fs-extra";
import path from "path";
import * as p from "@clack/prompts";
import pc from "picocolors";
import { RegistryClient, RegistryComponent } from "./registry.js";
import { readConfig, addComponentToConfig } from "./config-manager.js";
import { installDependencies } from "./dependencies.js";
import type { ProjectInfo } from "./project.js";

/**
 * Parse dependencies from a component
 */
function parseDependencies(component: RegistryComponent): {
  npmDependencies: string[];
} {
  const npmDependencies: string[] = [];

  if (component.dependencies) {
    if (Array.isArray(component.dependencies)) {
      // Old format: dependencies as array
      npmDependencies.push(...component.dependencies);
    } else if (typeof component.dependencies === 'object') {
      // New format: dependencies as object with npm key
      if (component.dependencies.npm) {
        npmDependencies.push(...component.dependencies.npm);
      }
    }
  }

  return { npmDependencies };
}

/**
 * Install a component from the registry
 */
export async function installComponent(
  name: string,
  projectInfo: ProjectInfo,
  cwd: string,
  options: {
    overwrite?: boolean;
    yes?: boolean;
    typescript?: boolean;
  } = {}
): Promise<void> {
  const config = await readConfig(cwd);
  if (!config) {
    throw new Error("Backternity not initialized. Run 'backternity init' first.");
  }

  const registryClient = new RegistryClient({ 
    url: config.registry,
    useTypeScript: options.typescript || false
  });
  
  const s = p.spinner();
  s.start(`Fetching ${options.typescript ? 'TypeScript ' : ''}component ${pc.cyan(name)}...`);

  // Fetch component from registry
  const component = await registryClient.fetchComponent(name);
  if (!component) {
    s.stop(pc.red(`❌ Component ${name} not found in registry`));
    throw new Error(`Component ${name} not found`);
  }

  s.message(`Found ${component.name} v${component.version}`);

  // Check if component is already installed
  const isInstalled = config.components.some(c => c.name === component.name);
  if (isInstalled && !options.overwrite) {
    if (!options.yes) {
      const shouldOverwrite = await p.confirm({
        message: `Component ${component.name} is already installed. Overwrite?`,
      });

      if (p.isCancel(shouldOverwrite) || !shouldOverwrite) {
        s.stop(pc.yellow("Installation cancelled"));
        return;
      }
    }
  }

  s.message("Installing component files...");

  // Parse dependencies from component
  const { npmDependencies } = parseDependencies(component);

  // Create component files
  for (const file of component.files) {
    const filePath = resolveFilePath(file.path, config, projectInfo, cwd);
    await fs.ensureDir(path.dirname(filePath));
    
    // Process file content (replace aliases, etc.)
    const processedContent = processFileContent(file.content, config);
    await fs.writeFile(filePath, processedContent);
  }

  s.message("Installing npm dependencies...");

  // Install npm dependencies
  if (npmDependencies.length > 0) {
    await installDependencies(npmDependencies, projectInfo, cwd);
  }

  // Note: Registry dependencies (other backternity components) can be added to the schema later if needed

  // Update configuration
  await addComponentToConfig(cwd, component.name, component.version);

  const tsIndicator = options.typescript ? pc.cyan(" (TypeScript)") : "";
  s.stop(pc.green(`✅ Component ${component.name}${tsIndicator} installed successfully!`));

  // Create documentation file if available
  await createComponentDocumentation(component, cwd, config, projectInfo);
}

/**
 * Create component documentation file after installation
 */
/**
 * Create component documentation file after installation
 */
async function createComponentDocumentation(
  component: RegistryComponent,
  cwd: string,
  config: any,
  projectInfo: ProjectInfo
): Promise<void> {
  if (!component.documentation) return;

  // Start with header info
  let docsContent = `# ${component.name}\n\n`;
  docsContent += `**Version:** ${component.version}\n`;
  docsContent += `**Type:** ${component.type}\n`;
  if (component.description) {
    docsContent += `**Description:** ${component.description}\n`;
  }
  docsContent += `\n---\n\n`;

  // Just append Markdown directly
  docsContent += component.documentation.trim() + "\n\n";

  // Add dependency information
  if (component.dependencies) {
    docsContent += `## Dependencies\n\n`;
    if (Array.isArray(component.dependencies)) {
      docsContent += `- ${component.dependencies.join('\n- ')}\n\n`;
    } else if (component.dependencies.npm) {
      docsContent += `**NPM packages:**\n- ${component.dependencies.npm.join('\n- ')}\n\n`;
    }
  }

  // Add tags
  if (component.tags?.length) {
    docsContent += `## Tags\n\n${component.tags.join(', ')}\n\n`;
  }

  docsContent += `---\n\n`;
  docsContent += `*Generated by Backternity CLI on ${new Date().toISOString()}*\n`;

  // Output path
  const docsDir = projectInfo.hasSrcDir ? path.join(cwd, "src", "docs") : path.join(cwd, "docs");
  const docsPath = path.join(docsDir, `${component.name}.md`);

  await fs.ensureDir(docsDir);
  await fs.writeFile(docsPath, docsContent);

  console.log("");
  p.log.success(pc.green(`📚 Documentation created: ${path.relative(cwd, docsPath)}`));
  console.log("");
}


/**
 * Resolve file path for server components
 */
function resolveFilePath(
  filePath: string,
  config: any,
  projectInfo: ProjectInfo,
  cwd: string
): string {
  // Remove @/ prefix and handle backend-specific paths
  let resolvedPath = filePath
    .replace(/^@\//, "") // Remove @/ prefix first
    .replace("routes", "routes")
    .replace("controllers", "controllers") 
    .replace("models", "models")
    .replace("middleware", "middleware")
    .replace("utils", "utils")
    .replace("lib", "lib")
    .replace("config", "config")
    .replace("services", "services");

  // Handle src directory
  if (projectInfo.hasSrcDir && !resolvedPath.startsWith("src/")) {
    resolvedPath = `src/${resolvedPath}`;
  }

  return path.resolve(cwd, resolvedPath);
}

/**
 * Process file content to replace aliases and placeholders for backend
 */
function processFileContent(content: string, config: any): string {
  // Replace @/ aliases with appropriate backend paths
  return content
    .replace(/@\/routes/g, config.aliases?.routes || "./routes")
    .replace(/@\/controllers/g, config.aliases?.controllers || "./controllers")
    .replace(/@\/models/g, config.aliases?.models || "./models") 
    .replace(/@\/middleware/g, config.aliases?.middleware || "./middleware")
    .replace(/@\/utils/g, config.aliases?.utils || "./utils")
    .replace(/@\/lib/g, config.aliases?.lib || "./lib")
    .replace(/@\/config/g, config.aliases?.config || "./config")
    .replace(/@\/services/g, config.aliases?.services || "./services");
}

/**
 * List available components from registry
 */
export async function listComponents(type?: string): Promise<RegistryComponent[]> {
  const config = await readConfig(process.cwd());
  const registryUrl = config?.registry || "https://registry.backternity.dev";
  
  const registryClient = new RegistryClient({ url: registryUrl });
  return registryClient.listComponents(type);
}

/**
 * Search components in registry
 */
export async function searchComponents(query: string): Promise<RegistryComponent[]> {
  const config = await readConfig(process.cwd());
  const registryUrl = config?.registry || "https://registry.backternity.dev";
  
  const registryClient = new RegistryClient({ url: registryUrl });
  return registryClient.searchComponents(query);
}