import { z } from "zod";
import { mockRegistry } from "./mock-registry.js";
import { typescriptRegistry } from "./typescript-registry.js";

// Registry configuration schema
export const registryConfigSchema = z.object({
  url: z.string().url(),
  token: z.string().optional(),
});

// Server sections schema for composable server.js merging
export const serverSectionsSchema = z.object({
  imports: z.array(z.string()).optional(),
  vars: z.array(z.string()).optional(),
  middlewares: z.array(z.string()).optional(),
  init: z.array(z.string()).optional(),
  routes: z.array(z.string()).optional(),
  endpoints: z.array(z.string()).optional(),
  errorHandlers: z.array(z.string()).optional(),
  listen: z.object({
    type: z.enum(["auto", "optional", "required"]).optional(),
    code: z.string(),
  }).optional(),
  shutdown: z.array(z.string()).optional(),
}).optional();

// Component schema for registry
export const registryComponentSchema = z.object({
  name: z.string(),
  description: z.string(),
  type: z.union([
    z.enum([
      "auth", "database", "analytics", "payment", "storage",
      "communication", "middleware", "utility", "validation",
      "logging", "caching", "service", "worker"
    ]),
    z.string() // fallback
  ]),
  version: z.string(),
  tags: z.array(z.string()).optional(),
  dependencies: z.object({
    npm: z.array(z.string()).optional(),
  }).optional(),
  files: z.array(z.object({
    path: z.string(),
    content: z.string(),
    type: z.enum([
      "route", "controller", "model", "middleware",
      "util", "config", "service", "lib", "document"
    ]),
  })),
  documentation: z.string().optional(),
  meta: z.object({
    requiresDatabase: z.boolean().optional(),
    requiresAuth: z.boolean().optional(),
    framework: z.enum(["express", "fastify", "node"]).optional(),
    serverType: z.enum(["api", "middleware", "utility", "service"]).optional(),
    style: z.enum(["default", "new-york"]).optional(),
  }).optional(),
});


export type RegistryConfig = z.infer<typeof registryConfigSchema>;
export type RegistryComponent = z.infer<typeof registryComponentSchema>;

// Default registry configuration - Live production registry
export const DEFAULT_REGISTRY_URL = "https://registry.backternity.dev";
export const DEFAULT_TYPESCRIPT_REGISTRY_URL = "https://registry.backternity.dev/typescript";

// Registry client class
export class RegistryClient {
  private baseUrl: string;
  private token?: string;
  private useTypeScript: boolean;

  constructor(config: RegistryConfig & { useTypeScript?: boolean }) {
    this.baseUrl = config.url;
    this.token = config.token;
    this.useTypeScript = config.useTypeScript || false;
  }

  async fetchComponent(name: string): Promise<RegistryComponent | null> {
    try {
      // Use local registry for localhost development
      if (this.baseUrl.includes("localhost") || this.baseUrl.includes("127.0.0.1")) {
        if (this.useTypeScript) {
          const data = await typescriptRegistry.getComponent(name);
          return data ? registryComponentSchema.parse(data) : null;
        } else {
          const data = await mockRegistry.getComponent(name);
          return data ? registryComponentSchema.parse(data) : null;
        }
      }

      // If TypeScript is requested, try to fetch from TypeScript registry path
      let componentUrl = `${this.baseUrl}/components/${name}`;
      if (this.useTypeScript) {
        componentUrl = `${this.baseUrl}/typescript-components/${name}`;
      }

      const response = await fetch(componentUrl, {
        headers: {
          ...(this.token && { Authorization: `Bearer ${this.token}` }),
        },
      });

      if (!response.ok) {
        return null;
      }

      const data = await response.json();
      return registryComponentSchema.parse(data);
    } catch (error) {
      console.error(`Failed to fetch component ${name}:`, error);
      return null;
    }
  }

  async listComponents(type?: string): Promise<RegistryComponent[]> {
    try {
      // Use local registry for localhost development
      if (this.baseUrl.includes("localhost") || this.baseUrl.includes("127.0.0.1")) {
        if (this.useTypeScript) {
          const data = await typescriptRegistry.listComponents(type);
          return z.array(registryComponentSchema).parse(data);
        } else {
          const data = await mockRegistry.listComponents(type);
          return z.array(registryComponentSchema).parse(data);
        }
      }

      const url = new URL(`${this.baseUrl}/${this.useTypeScript ? 'typescript-components' : 'components'}`);
      if (type) {
        url.searchParams.set("type", type);
      }

      const response = await fetch(url.toString(), {
        headers: {
          ...(this.token && { Authorization: `Bearer ${this.token}` }),
        },
      });

      if (!response.ok) {
        return [];
      }

      const data = await response.json();
      return z.array(registryComponentSchema).parse(data);
    } catch (error) {
      console.error("Failed to fetch components:", error);
      return [];
    }
  }

  async searchComponents(query: string): Promise<RegistryComponent[]> {
    try {
      // Use local registry for localhost development
      if (this.baseUrl.includes("localhost") || this.baseUrl.includes("127.0.0.1")) {
        if (this.useTypeScript) {
          const data = await typescriptRegistry.searchComponents(query);
          return z.array(registryComponentSchema).parse(data);
        } else {
          const data = await mockRegistry.searchComponents(query);
          return z.array(registryComponentSchema).parse(data);
        }
      }

      const url = new URL(`${this.baseUrl}/${this.useTypeScript ? 'typescript-components' : 'components'}/search`);
      url.searchParams.set("q", query);

      const response = await fetch(url.toString(), {
        headers: {
          ...(this.token && { Authorization: `Bearer ${this.token}` }),
        },
      });

      if (!response.ok) {
        return [];
      }

      const data = await response.json();
      return z.array(registryComponentSchema).parse(data);
    } catch (error) {
      console.error("Failed to search components:", error);
      return [];
    }
  }
}