import { z } from "zod";

// Project configuration schema for backend servers
export const backternityConfigSchema = z.object({
  $schema: z.string().optional(),
  registry: z.string().url().default("https://registry.backternity.dev"),
  framework: z.enum(["express", "fastify", "node"]).default("express"),
  typescript: z.boolean().default(true),
  aliases: z.object({
    routes: z.string().default("@/routes"),
    controllers: z.string().default("@/controllers"),
    models: z.string().default("@/models"),
    middleware: z.string().default("@/middleware"),
    utils: z.string().default("@/utils"),
    lib: z.string().default("@/lib"),
    config: z.string().default("@/config"),
    services: z.string().default("@/services"),
  }).default({}),
  components: z.array(z.object({
    name: z.string(),
    version: z.string(),
    installedAt: z.string(),
  })).default([]),
});

export type BackternityConfig = z.infer<typeof backternityConfigSchema>;

// Default configuration for backend servers
export const DEFAULT_CONFIG: BackternityConfig = {
  registry: "https://registry.backternity.dev",
  framework: "express",
  typescript: true,
  aliases: {
    routes: "@/routes",
    controllers: "@/controllers", 
    models: "@/models",
    middleware: "@/middleware",
    utils: "@/utils",
    lib: "@/lib",
    config: "@/config",
    services: "@/services",
  },
  components: [],
};

// Component installation status
export interface ComponentStatus {
  name: string;
  version: string;
  installed: boolean;
  updateAvailable: boolean;
  latestVersion?: string;
}