import fs from "fs-extra";
import path from "path";
import { BackternityConfig, backternityConfigSchema, DEFAULT_CONFIG } from "./config.js";

const CONFIG_FILE = "backternity.json";

/**
 * Get the configuration file path for a project
 */
export function getConfigPath(cwd: string): string {
  return path.resolve(cwd, CONFIG_FILE);
}

/**
 * Check if backternity is initialized in the project
 */
export async function isBackternityInitialized(cwd: string): Promise<boolean> {
  return fs.pathExists(getConfigPath(cwd));
}

/**
 * Read the backternity configuration
 */
export async function readConfig(cwd: string): Promise<BackternityConfig | null> {
  const configPath = getConfigPath(cwd);
  
  if (!(await fs.pathExists(configPath))) {
    return null;
  }

  try {
    const content = await fs.readFile(configPath, "utf-8");
    const rawConfig = JSON.parse(content);
    return backternityConfigSchema.parse(rawConfig);
  } catch (error) {
    console.error("Failed to read backternity config:", error);
    return null;
  }
}

/**
 * Write the backternity configuration
 */
export async function writeConfig(cwd: string, config: BackternityConfig): Promise<void> {
  const configPath = getConfigPath(cwd);
  const configWithSchema = {
    $schema: "https://registry.backternity.dev/schema.json",
    ...config,
  };
  
  await fs.writeFile(configPath, JSON.stringify(configWithSchema, null, 2));
}

/**
 * Initialize backternity configuration
 */
export async function initializeConfig(cwd: string, overrides: Partial<BackternityConfig> = {}): Promise<BackternityConfig> {
  const config = { ...DEFAULT_CONFIG, ...overrides };
  await writeConfig(cwd, config);
  return config;
}

/**
 * Update configuration with new values
 */
export async function updateConfig(cwd: string, updates: Partial<BackternityConfig>): Promise<BackternityConfig> {
  const existingConfig = await readConfig(cwd) || DEFAULT_CONFIG;
  const newConfig = { ...existingConfig, ...updates };
  await writeConfig(cwd, newConfig);
  return newConfig;
}

/**
 * Add a component to the configuration
 */
export async function addComponentToConfig(
  cwd: string,
  name: string,
  version: string
): Promise<void> {
  const config = await readConfig(cwd) || DEFAULT_CONFIG;
  
  // Remove existing component if it exists
  config.components = config.components.filter(c => c.name !== name);
  
  // Add new component
  config.components.push({
    name,
    version,
    installedAt: new Date().toISOString(),
  });
  
  await writeConfig(cwd, config);
}

/**
 * Remove a component from the configuration
 */
export async function removeComponentFromConfig(cwd: string, name: string): Promise<void> {
  const config = await readConfig(cwd) || DEFAULT_CONFIG;
  config.components = config.components.filter(c => c.name !== name);
  await writeConfig(cwd, config);
}