#!/usr/bin/env node

/**
 * Backternity CLI - Registry-based Full-stack Components
 * Backend component registry for Express/Node.js servers
 */

import * as p from "@clack/prompts";
import pc from "picocolors";
import path from "path";
import fs from "fs-extra";
import { Command } from "commander";
import { detectProject, type ProjectInfo } from "./utils/project.js";
import { 
  installComponent, 
  listComponents, 
  searchComponents 
} from "./utils/component-installer.js";
import { 
  isBackternityInitialized, 
  initializeConfig, 
  readConfig 
} from "./utils/config-manager.js";
import type { RegistryComponent } from "./utils/registry.js";
import { marked } from "marked";
import TerminalRenderer from "marked-terminal";

marked.setOptions({
  renderer: (new TerminalRenderer({
    code: pc.cyan, // color for code blocks
    heading: pc.bold, // headings
    firstHeading: pc.green, // top-level title
    tab: 2,
    reflowText: true,
    emoji: true,
  }) as unknown) as any,
});

interface GlobalOptions {
  cwd: string;
}

interface AddOptions extends GlobalOptions {
  yes: boolean;
  overwrite: boolean;
  typescript: boolean;
}

interface InitOptions extends GlobalOptions {
  yes: boolean;
  registry?: string;
}

async function main() {
  const program = new Command()
    .name("backternity")
    .description("Add full-stack components to your project")
    .version("0.2.0");

  // Global options
  program
    .option("-c, --cwd <cwd>", "working directory", process.cwd());

  // Init command
  program
    .command("init")
    .description("Initialize backternity in your project")
    .option("-y, --yes", "skip confirmation prompts", false)
    .option("--registry <url>", "registry URL")
    .action(async (options: InitOptions) => {
      try {
        await runInit(options);
      } catch (error) {
        handleError(error);
      }
    });

  // Add command
  program
    .command("add")
    .description("Add components from the registry")
    .argument("[components...]", "components to add")
    .option("-y, --yes", "skip confirmation prompts", false)
    .option("--overwrite", "overwrite existing components", false)
    .option("--typescript", "install TypeScript version of component", false)
    .action(async (components: string[], options: AddOptions) => {
      try {
        await runAdd(components, options);
      } catch (error) {
        handleError(error);
      }
    });

  // List command
  program
    .command("list")
    .description("List available components")
    .option("--type <type>", "filter by component type")
    .action(async (options: { type?: string } & GlobalOptions) => {
      try {
        await runList(options);
      } catch (error) {
        handleError(error);
      }
    });

  // Search command
  program
    .command("search")
    .description("Search for components")
    .argument("<query>", "search query")
    .action(async (query: string, options: GlobalOptions) => {
      try {
        await runSearch(query, options);
      } catch (error) {
        handleError(error);
      }
    });

  // Update command
  program
    .command("update")
    .description("Update components to latest versions")
    .argument("[components...]", "components to update (all if none specified)")
    .action(async (components: string[], options: GlobalOptions) => {
      try {
        await runUpdate(components, options);
      } catch (error) {
        handleError(error);
      }
    });

  // Documentation command
  program
    .command("docs")
    .description("View component documentation")
    .argument("[component]", "component name to view docs for")
    .action(async (component: string | undefined, options: GlobalOptions) => {
      try {
        await runDocs(options, component);
      } catch (error) {
        handleError(error);
      }
    });

  program.parse();
}

async function handleNewExpressProject() {
  p.note(
    `To bootstrap a new Express.js project, follow these steps:
  
  1. Initialize Node.js project:
     ${pc.cyan("npm init -y")}
  
  2. Install Express foundation:
     ${pc.cyan("npx backternity@latest add expressjs-foundation")}
  
This will set up a complete Express.js foundation for you.`,
    "Getting Started"
  );
  process.exit(0);
}

async function runInit(options: InitOptions) {
  console.clear();
  p.intro(pc.cyan("⚡ Backternity"));

  const cwd = path.resolve(options.cwd || process.cwd());

  // Check if already initialized
  if (await isBackternityInitialized(cwd)) {
    if (!options.yes) {
      const shouldReinitialize = await p.confirm({
        message: "Backternity is already initialized. Reinitialize?",
      });

      if (p.isCancel(shouldReinitialize) || !shouldReinitialize) {
        p.cancel("Operation cancelled");
        process.exit(0);
      }
    }
  }

  // Detect project
  const projectInfo = await detectProject(cwd);
  let framework = projectInfo.framework;

  if (projectInfo.framework === "unknown") {
    p.log.warn(
      pc.yellow("⚠️  Could not detect a supported backend framework (Express, Fastify, or Node.js)")
    );
    
    const startWithExpress = await p.confirm({
      message: "Would you like to start a new Express.js project?",
      initialValue: true,
    });

    if (p.isCancel(startWithExpress)) {
      p.cancel("Operation cancelled");
      process.exit(0);
    }

    if (startWithExpress) {
      await handleNewExpressProject();
    } else {
      p.cancel("No framework selected");
      process.exit(1);
    }
  }

  // Configuration
  const frameworkSelection = await p.select({
    message: "Which backend framework are you using?",
    options: [
      { value: "express", label: "Express" },
      { value: "fastify", label: "Fastify" },
      { value: "node", label: "Node.js" },
    ],
    initialValue: (projectInfo.framework === "express" || projectInfo.framework === "fastify" || projectInfo.framework === "node") 
      ? projectInfo.framework 
      : "express",
  });

  if (p.isCancel(frameworkSelection)) {
    p.cancel("Operation cancelled");
    process.exit(0);
  }
  framework = frameworkSelection as "express" | "fastify" | "node";

  const config = await initializeConfig(cwd, {
    registry: options.registry,
    framework: framework as "express" | "fastify" | "node",
    typescript: projectInfo.hasTypeScript ?? true,
  });

  p.log.success(pc.green("✅ Backternity initialized!"));
  p.note(
    `Configuration saved to ${pc.cyan("backternity.json")}
    
Next steps:
  1. Browse components: ${pc.cyan("backternity list")}
  2. Add a component: ${pc.cyan("backternity add auth-jwt")}
  3. Search components: ${pc.cyan("backternity search auth")}`,
    "Setup Complete"
  );
}

async function runAdd(components: string[], options: AddOptions) {
  console.clear();
  p.intro(pc.cyan("⚡ Backternity"));

  const cwd = path.resolve(options.cwd || process.cwd());

  // Check if this is a foundation component (can be installed without init)
  const isFoundationComponent = components.length > 0 && 
    (components[0] === "expressjs-foundation" || 
     components[0].includes("foundation") ||
     components[0].includes("starter"));

  // Check if package.json exists
  const packageJsonPath = path.join(cwd, "package.json");
  const hasPackageJson = await fs.pathExists(packageJsonPath);

  if (!hasPackageJson) {
    p.log.error(pc.red("❌ No package.json found in current directory"));
    p.note(
      `Please initialize a Node.js project first:
  ${pc.cyan("npm init -y")}
  
Then run this command again.`,
      "Setup Required"
    );
    process.exit(1);
  }

  // Check if initialized
  if (!(await isBackternityInitialized(cwd))) {
    if (isFoundationComponent) {
      // Foundation components can auto-initialize
      p.log.info(pc.yellow("⚡ Initializing Backternity for foundation setup..."));
      
      // Auto-initialize with sensible defaults
      await initializeConfig(cwd, {
        framework: "express",
        typescript: true,
      });
      
      p.log.success(pc.green("✅ Backternity initialized!"));
    } else {
      p.log.error(pc.red("❌ Backternity not initialized. Run 'backternity init' first."));
      process.exit(1);
    }
  }

  const projectInfo = await detectProject(cwd);

  // If no components specified, show interactive selection
  if (components.length === 0) {
    const availableComponents = await listComponents();
    
    if (availableComponents.length === 0) {
      p.log.warn(pc.yellow("No components available in registry"));
      process.exit(0);
    }

    const selected = await p.select({
      message: "Which component would you like to add?",
      options: availableComponents.map(comp => ({
        value: comp.name,
        label: `${comp.name} - ${comp.description}`,
        hint: comp.version,
      })),
    });

    if (p.isCancel(selected)) {
      p.cancel("Operation cancelled");
      process.exit(0);
    }

    components = [selected as string];
  }

  // Install each component
  for (const componentName of components) {
    try {
      await installComponent(componentName, projectInfo, cwd, options);
    } catch (error) {
      p.log.error(pc.red(`Failed to install ${componentName}: ${error}`));
    }
  }

  p.outro(pc.green("🚀 Components installed successfully!"));
}

async function runList(options: { type?: string } & GlobalOptions) {
  console.clear();
  p.intro(pc.cyan("⚡ Available Components"));

  const components = await listComponents(options.type);
  
  if (components.length === 0) {
    p.log.warn(pc.yellow("No components found"));
    return;
  }

  // Group by type
  const groupedComponents = components.reduce((acc, comp) => {
    if (!acc[comp.type]) acc[comp.type] = [];
    acc[comp.type].push(comp);
    return acc;
  }, {} as Record<string, RegistryComponent[]>);

  for (const [type, comps] of Object.entries(groupedComponents)) {
    p.log.info(pc.bold(pc.cyan(`\n${type.toUpperCase()}`)));
    for (const comp of comps) {
      p.log.info(`  ${pc.green(comp.name)} - ${comp.description} ${pc.dim(`(v${comp.version})`)}`);
    }
  }

  p.outro(pc.dim("Use 'backternity add <component>' to install"));
}

async function runSearch(query: string, options: GlobalOptions) {
  console.clear();
  p.intro(pc.cyan(`🔍 Search: "${query}"`));

  const components = await searchComponents(query);
  
  if (components.length === 0) {
    p.log.warn(pc.yellow("No components found"));
    return;
  }

  for (const comp of components) {
    p.log.info(`${pc.green(comp.name)} - ${comp.description} ${pc.dim(`(v${comp.version})`)}`);
    if (comp.tags && comp.tags.length > 0) {
      p.log.info(`  ${pc.dim("Tags:")} ${comp.tags.join(", ")}`);
    }
  }

  p.outro(pc.dim("Use 'backternity add <component>' to install"));
}

async function runUpdate(components: string[], options: GlobalOptions) {
  console.clear();
  p.intro(pc.cyan("🔄 Update Components"));

  const cwd = path.resolve(options.cwd || process.cwd());
  const config = await readConfig(cwd);
  
  if (!config) {
    p.log.error(pc.red("❌ Backternity not initialized"));
    process.exit(1);
  }

  const projectInfo = await detectProject(cwd);

  // If no components specified, update all
  if (components.length === 0) {
    components = config.components.map(c => c.name);
  }

  for (const componentName of components) {
    try {
      await installComponent(componentName, projectInfo, cwd, { overwrite: true, yes: true });
    } catch (error) {
      p.log.error(pc.red(`Failed to update ${componentName}: ${error}`));
    }
  }

  p.outro(pc.green("🚀 Components updated successfully!"));
}


async function runDocs(options: GlobalOptions, componentName?: string) {
  console.clear();
  p.intro(pc.cyan("📚 Component Documentation"));

  const cwd = path.resolve(options.cwd || process.cwd());
  
  if (!componentName) {
    // Show list of installed components
    const config = await readConfig(cwd);
    if (!config) {
      p.log.error(pc.red("❌ Backternity not initialized"));
      process.exit(1);
    }

    if (config.components.length === 0) {
      p.log.warn(pc.yellow("No components installed yet"));
      p.log.info("Install a component first: " + pc.cyan("backternity add auth-jwt"));
      process.exit(0);
    }

    const selected = await p.select({
      message: "Which component's documentation would you like to view?",
      options: config.components.map(comp => ({
        value: comp.name,
        label: `${comp.name} (v${comp.version})`,
      })),
    });

    if (p.isCancel(selected)) {
      p.cancel("Operation cancelled");
      process.exit(0);
    }

    componentName = selected as string;
  }

  // Fetch component documentation
  try {
    const availableComponents = await listComponents();
    const component = availableComponents.find(c => c.name === componentName);
    
    if (!component) {
      p.log.error(pc.red(`❌ Component ${componentName} not found in registry`));
      process.exit(1);
    }

    if (!component.documentation) {
      p.log.warn(pc.yellow(`📝 No documentation available for ${componentName}`));
      p.log.info("Consider contributing documentation to the registry!");
      process.exit(0);
    }

    // Display documentation using the same function from component-installer
    console.log("");
    displayComponentDocumentation(component);
    
  } catch (error) {
    p.log.error(pc.red(`Failed to fetch documentation: ${error}`));
    process.exit(1);
  }

  p.outro(pc.dim("Use 'backternity docs <component>' to view specific component docs"));
}

// Import displayComponentDocumentation function (we'll need to make it exportable)
export function displayComponentDocumentation(component: RegistryComponent): void {
  if (!component.documentation) return;

  console.log("");
  p.log.info(pc.bold(pc.cyan(`📚 ${component.name} Documentation`)));
  console.log("");

  // Render the markdown directly in styled form
  const rendered = marked.parse(component.documentation);
  console.log(rendered);

  console.log(pc.gray("\n──────────────────────────────"));
  console.log(pc.dim("*End of documentation*\n"));
}


function handleError(error: any) {
  p.log.error(
    pc.red(`Error: ${error instanceof Error ? error.message : String(error)}`)
  );
  process.exit(1);
}

main().catch(handleError);