import { execa } from "execa";
import type { ProjectInfo } from "./project.js";

/**
 * Install dependencies using the project's package manager
 */
export async function installDependencies(
  dependencies: string[],
  projectInfo: ProjectInfo,
  cwd: string
): Promise<void> {
  if (!dependencies || dependencies.length === 0) {
    return;
  }

  const { packageManager } = projectInfo;

  const commands: Record<string, { cmd: string; args: string[] }> = {
    npm: { cmd: "npm", args: ["install", ...dependencies] },
    pnpm: { cmd: "pnpm", args: ["add", ...dependencies] },
    yarn: { cmd: "yarn", args: ["add", ...dependencies] },
    bun: { cmd: "bun", args: ["add", ...dependencies] },
  };

  const { cmd, args } = commands[packageManager];

  await execa(cmd, args, {
    cwd,
    stdio: "inherit",
  });
}
