import fs from "fs-extra";
import path from "path";
import { fileURLToPath } from "url";

// Get current module directory - works in both ESM and after bundling
function getCurrentDir(): string {
  try {
    // Try ESM approach first
    if (typeof import.meta !== 'undefined' && import.meta.url) {
      return path.dirname(fileURLToPath(import.meta.url));
    }
  } catch (e) {
    // Fall back to other methods
  }
  
  try {
    // Try to use __dirname if available (in CJS or after bundling)
    if (typeof __dirname !== 'undefined') {
      return __dirname;
    }
  } catch (e) {
    // Continue to fallback
  }
  
  // Final fallback
  return process.cwd();
}

/**
 * Mock registry server for local development
 * In production, this would be a real server with API endpoints
 */
export class MockRegistryServer {
  private registryPath: string;

  constructor() {
    const currentDir = getCurrentDir();
    
    // Try multiple potential locations for the registry
    const possiblePaths = [
      // When running via npx, look in the package installation
      path.resolve(currentDir, "../registry"),
      path.resolve(currentDir, "../../registry"), 
      path.resolve(currentDir, "../dist/registry"),
      // Development mode - local paths
      path.resolve(process.cwd(), "dist/registry"), 
      path.resolve(process.cwd(), "registry"),
      // Try relative to module location
      path.join(currentDir, "..", "registry"),
    ];

    // Use the first path that exists
    this.registryPath = possiblePaths.find(p => {
      try {
        return fs.existsSync(p);
      } catch {
        return false;
      }
    }) || possiblePaths[0]; // Fallback to first path
  }

  async getComponent(name: string) {
    const componentPath = path.join(this.registryPath, `${name}.json`);
    
    if (!(await fs.pathExists(componentPath))) {
      return null;
    }

    const content = await fs.readFile(componentPath, "utf-8");
    return JSON.parse(content);
  }

  async listComponents(type?: string) {
    const files = await fs.readdir(this.registryPath);
    const components = [];

    for (const file of files) {
      if (file.endsWith(".json")) {
        const componentPath = path.join(this.registryPath, file);
        const content = await fs.readFile(componentPath, "utf-8");
        const component = JSON.parse(content);
        
        if (!type || component.type === type) {
          components.push(component);
        }
      }
    }

    return components;
  }

  async searchComponents(query: string) {
    const allComponents = await this.listComponents();
    const lowerQuery = query.toLowerCase();
    
    return allComponents.filter(component => 
      component.name.toLowerCase().includes(lowerQuery) ||
      component.description.toLowerCase().includes(lowerQuery) ||
      component.tags?.some((tag: string) => tag.toLowerCase().includes(lowerQuery))
    );
  }
}

// For development, use local registry
export const mockRegistry = new MockRegistryServer();