import path from "path";
import { fileURLToPath } from "url";
import fs from "fs-extra";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

/**
 * TypeScript Registry - Local file-based registry for TypeScript components
 */
export const typescriptRegistry = {
  async getComponent(name: string) {
    const registryPath = path.resolve(__dirname, "../../typescript-registry");
    const componentPath = path.join(registryPath, `${name}.json`);
    
    if (await fs.pathExists(componentPath)) {
      const content = await fs.readJson(componentPath);
      return content;
    }
    
    return null;
  },

  async listComponents(type?: string) {
    const registryPath = path.resolve(__dirname, "../../typescript-registry");
    
    if (!(await fs.pathExists(registryPath))) {
      return [];
    }
    
    const files = await fs.readdir(registryPath);
    const components = [];

    for (const file of files) {
      if (file.endsWith(".json")) {
        const content = await fs.readJson(path.join(registryPath, file));
        if (!type || content.type === type) {
          components.push(content);
        }
      }
    }

    return components;
  },

  async searchComponents(query: string) {
    const allComponents = await this.listComponents();
    const lowerQuery = query.toLowerCase();

    return allComponents.filter(
      (comp: any) =>
        comp.name.toLowerCase().includes(lowerQuery) ||
        comp.description?.toLowerCase().includes(lowerQuery) ||
        comp.tags?.some((tag: string) => tag.toLowerCase().includes(lowerQuery))
    );
  },
};
